package com.aref.jarvis;
import android.content.*;import android.telephony.*;import android.provider.Telephony;import java.util.*;
public class SmsReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){if(!Telephony.Sms.Intents.SMS_RECEIVED_ACTION.equals(i.getAction()))return;final Store s=new Store(c);if(!s.away)return;final HashMap<String,StringBuilder> grouped=new HashMap<>();for(SmsMessage m:Telephony.Sms.Intents.getMessagesFromIntent(i)){String n=m.getOriginatingAddress(),b=m.getMessageBody();if(n!=null&&b!=null)grouped.computeIfAbsent(n,k->new StringBuilder()).append(b);}
 for(String from:grouped.keySet()){String body=grouped.get(from).toString();if(s.seen(from,body))continue;PendingResult pr=goAsync();new Thread(()->{JarvisDb db=new JarvisDb(c);try{String name=ContactHelper.name(c,from);db.message(from,name,body,0,"received");String context=db.recent(from,12);String prompt="SMS از "+(name.isEmpty()?from:name)+" دریافت شده. تاریخچه مرتبط:\n"+context+"\nپیام جدید:\n"+body+"\nقوانین:\n"+s.rules+"\nیک پاسخ طبیعی و کوتاه تولید کن. فقط متن پاسخ را برگردان.";String answer=GeminiClient.ask(s,prompt);if(RuleEngine.allow(from,body,answer,s)){SmsManager.getDefault().sendTextMessage(from,null,answer,null,null);s.markReply(from);db.message(from,name,answer,1,"sent");db.event("sms_reply","پاسخ خودکار برای "+from);s.addLog("SMS ← "+from+"\nJARVIS → "+answer);}else{db.event("reply_blocked","پاسخ برای "+from+" توسط قوانین/محدودیت رد شد");s.addLog("پاسخ ارسال نشد ← "+from);}}catch(Exception e){db.event("error",e.getMessage()==null?"unknown":e.getMessage());s.addLog("خطا در SMS ← "+e.getMessage());}finally{db.close();pr.finish();}}).start();}}
}